INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, acceptable_answers, diagnostic_rubric, explanation, order_index)
VALUES
  ('d2000001-0000-4000-8000-000000000001', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「あ」 (a) dengan mengikuti panduan goresan.', '{"target_character":"あ","script":"hiragana","romaji":"a","meaning":"Huruf a (contoh: あさ = pagi)","mnemonic":"Mulai dari garis datar atas, tarik lengkung vertikal ke bawah, lalu buat simpul melingkar seperti huruf ''a''.","audio_text":"あ"}'::jsonb, '"あ"'::jsonb, '["あ"]'::jsonb, NULL, 'Huruf Hiragana あ (a) ditulis dalam 3 goresan: mendatar, melengkung ke bawah, lalu simpul melingkar.', 11),
  ('d2000001-0000-4000-8000-000000000002', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「い」 (i) dengan mengikuti panduan goresan.', '{"target_character":"い","script":"hiragana","romaji":"i","meaning":"Huruf i (contoh: いえ = rumah)","mnemonic":"Dua garis lengkung berhadapan seperti dua ekor ikan kecil; goresan kiri lebih panjang dengan kait kecil di ujung.","audio_text":"い"}'::jsonb, '"い"'::jsonb, '["い"]'::jsonb, NULL, 'Huruf Hiragana い (i) terdiri dari 2 goresan lembut dari atas ke bawah, sisi kiri sedikit lebih panjang.', 12),
  ('d2000001-0000-4000-8000-000000000003', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「う」 (u) dengan mengikuti panduan goresan.', '{"target_character":"う","script":"hiragana","romaji":"u","meaning":"Huruf u (contoh: うみ = laut)","mnemonic":"Coretan miring pendek di atas diikuti lengkungan besar ke kanan lalu menyapu turun seperti telinga.","audio_text":"う"}'::jsonb, '"う"'::jsonb, '["う"]'::jsonb, NULL, 'Huruf Hiragana う (u) ditulis dalam 2 goresan: garis pendek di atas, lalu lengkungan lebar ke bawah.', 13),
  ('d2000001-0000-4000-8000-000000000004', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「え」 (e) dengan mengikuti panduan goresan.', '{"target_character":"え","script":"hiragana","romaji":"e","meaning":"Huruf e (contoh: えき = stasiun)","mnemonic":"Garis pendek miring di atas, lalu gerakan zig-zag seperti huruf Z yang melengkung lembut di akhir.","audio_text":"え"}'::jsonb, '"え"'::jsonb, '["え"]'::jsonb, NULL, 'Huruf Hiragana え (e) terdiri dari 2 goresan; perhatikan garis kedua yang mengalir kontinu tanpa terputus.', 14),
  ('d2000001-0000-4000-8000-000000000005', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「お」 (o) dengan mengikuti panduan goresan.', '{"target_character":"お","script":"hiragana","romaji":"o","meaning":"Huruf o (contoh: おちゃ = teh)","mnemonic":"Garis datar pendek, garis vertikal berputar membulat ke kanan, lalu diakhiri titik kecil di kanan atas.","audio_text":"お"}'::jsonb, '"お"'::jsonb, '["お"]'::jsonb, NULL, 'Huruf Hiragana お (o) memiliki 3 goresan dan dibedakan dari あ lewat titik kecil di sisi kanan atas.', 15),
  ('d2000001-0000-4000-8000-000000000006', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「か」 (ka) dengan mengikuti panduan goresan.', '{"target_character":"か","script":"hiragana","romaji":"ka","meaning":"Huruf ka (contoh: かお = wajah)","mnemonic":"Lengkungan ke kanan dengan sudut turun dan kait, disilang garis miring, lalu titik pendek di kanan atas.","audio_text":"か"}'::jsonb, '"か"'::jsonb, '["か"]'::jsonb, NULL, 'Huruf Hiragana か (ka) ditulis dalam 3 goresan: sudut berkait, garis silang miring, dan titik kanan.', 16),
  ('d2000001-0000-4000-8000-000000000007', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「き」 (ki) dengan mengikuti panduan goresan.', '{"target_character":"き","script":"hiragana","romaji":"ki","meaning":"Huruf ki (contoh: きく = mendengar)","mnemonic":"Dua garis mendatar sejajar disilang garis miring ke kanan bawah, lalu lengkungan lembut di bagian bawah seperti kunci.","audio_text":"き"}'::jsonb, '"き"'::jsonb, '["き"]'::jsonb, NULL, 'Huruf Hiragana き (ki) ditulis dalam 4 goresan terpisah pada gaya cetak buku pelajaran.', 17),
  ('d2000001-0000-4000-8000-000000000008', 'b0000026-0000-0000-0000-000000000201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「さ」 (sa) dengan mengikuti panduan goresan.', '{"target_character":"さ","script":"hiragana","romaji":"sa","meaning":"Huruf sa (contoh: さくら = sakura)","mnemonic":"Satu garis mendatar disilang garis miring turun, lalu lengkungan senyum di bagian bawah.","audio_text":"さ"}'::jsonb, '"さ"'::jsonb, '["さ"]'::jsonb, NULL, 'Huruf Hiragana さ (sa) mirip き namun hanya memiliki satu garis mendatar di bagian atas (3 goresan).', 11),
  ('d2000001-0000-4000-8000-000000000009', 'b0000026-0000-0000-0000-000000000201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「し」 (shi) dengan mengikuti panduan goresan.', '{"target_character":"し","script":"hiragana","romaji":"shi","meaning":"Huruf shi (contoh: しろ = putih)","mnemonic":"Satu goresan tunggal lurus ke bawah lalu melengkung halus ke kanan atas seperti kail pancing.","audio_text":"し"}'::jsonb, '"し"'::jsonb, '["し"]'::jsonb, NULL, 'Huruf Hiragana し (shi) ditulis dalam 1 goresan mengalir tanpa mengangkat pena.', 12),
  ('d2000001-0000-4000-8000-000000000010', 'b0000026-0000-0000-0000-000000000201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「た」 (ta) dengan mengikuti panduan goresan.', '{"target_character":"た","script":"hiragana","romaji":"ta","meaning":"Huruf ta (contoh: たべる = makan)","mnemonic":"Tanda tambah sedikit miring di kiri, lalu dua garis lengkung kecil sejajar di kanan seperti huruf ''t'' dan ''a''.","audio_text":"た"}'::jsonb, '"た"'::jsonb, '["た"]'::jsonb, NULL, 'Huruf Hiragana た (ta) terdiri dari 4 goresan: dua goresan di sisi kiri dan dua goresan menyerupai こ di kanan.', 13),
  ('d2000001-0000-4000-8000-000000000011', 'b0000026-0000-0000-0000-000000000201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「つ」 (tsu) dengan mengikuti panduan goresan.', '{"target_character":"つ","script":"hiragana","romaji":"tsu","meaning":"Huruf tsu (contoh: つき = bulan)","mnemonic":"Satu lengkungan besar dari kiri ke kanan lalu membelok turun ke kiri bawah seperti gulungan ombak.","audio_text":"つ"}'::jsonb, '"つ"'::jsonb, '["つ"]'::jsonb, NULL, 'Huruf Hiragana つ (tsu) ditulis dalam 1 goresan lebar dan membulat.', 14),
  ('d2000001-0000-4000-8000-000000000012', 'b0000026-0000-0000-0000-000000000201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「な」 (na) dengan mengikuti panduan goresan.', '{"target_character":"な","script":"hiragana","romaji":"na","meaning":"Huruf na (contoh: なまえ = nama)","mnemonic":"Tanda silang di kiri atas, titik miring di kanan atas, lalu simpul kecil melingkar di bagian bawah.","audio_text":"な"}'::jsonb, '"な"'::jsonb, '["な"]'::jsonb, NULL, 'Huruf Hiragana な (na) ditulis dalam 4 goresan dengan simpul lembut di kaki kanan bawah.', 15),
  ('d2000001-0000-4000-8000-000000000013', 'b0000026-0000-0000-0000-000000000301', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「は」 (ha) dengan mengikuti panduan goresan.', '{"target_character":"は","script":"hiragana","romaji":"ha","meaning":"Huruf ha (contoh: はな = bunga)","mnemonic":"Garis vertikal kiri dengan sedikit kait, lalu garis mendatar kanan dipotong garis turun yang diakhiri simpul kecil.","audio_text":"は"}'::jsonb, '"は"'::jsonb, '["は"]'::jsonb, NULL, 'Huruf Hiragana は (ha) memiliki 3 goresan dan juga berfungsi sebagai partikel topik kalimat (dibaca ''wa'').', 11),
  ('d2000001-0000-4000-8000-000000000014', 'b0000026-0000-0000-0000-000000000301', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「ま」 (ma) dengan mengikuti panduan goresan.', '{"target_character":"ま","script":"hiragana","romaji":"ma","meaning":"Huruf ma (contoh: まち = kota)","mnemonic":"Dua garis mendatar sejajar dipotong garis vertikal tengah yang berputar membentuk simpul di bawah.","audio_text":"ま"}'::jsonb, '"ま"'::jsonb, '["ま"]'::jsonb, NULL, 'Huruf Hiragana ま (ma) terdiri dari 3 goresan; perhatikan garis datar atas lebih panjang dari yang bawah.', 12),
  ('d2000001-0000-4000-8000-000000000015', 'b0000026-0000-0000-0000-000000000401', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「ら」 (ra) dengan mengikuti panduan goresan.', '{"target_character":"ら","script":"hiragana","romaji":"ra","meaning":"Huruf ra (contoh: らいしゅう = minggu depan)","mnemonic":"Titik pendek di atas, lalu garis turun yang langsung melengkung besar ke kanan seperti angka 5.","audio_text":"ら"}'::jsonb, '"ら"'::jsonb, '["ら"]'::jsonb, NULL, 'Huruf Hiragana ら (ra) ditulis dalam 2 goresan yang tegas dan seimbang.', 11),
  ('d2000001-0000-4000-8000-000000000016', 'b0000026-0000-0000-0000-000000000401', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Hiragana 「ん」 (n) dengan mengikuti panduan goresan.', '{"target_character":"ん","script":"hiragana","romaji":"n","meaning":"Huruf n (contoh: にほん = Jepang)","mnemonic":"Satu goresan miring turun ke kiri, memantul naik membentuk bukit kecil, lalu berakhir naik ke kanan seperti huruf ''h''.","audio_text":"ん"}'::jsonb, '"ん"'::jsonb, '["ん"]'::jsonb, NULL, 'Huruf Hiragana ん (n) adalah satu-satunya konsonan berdiri sendiri dalam Hiragana (1 goresan).', 12),
  ('d2000001-0000-4000-8000-000000000017', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ア」 (a) dengan mengikuti panduan goresan.', '{"target_character":"ア","script":"katakana","romaji":"a","meaning":"Katakana a (contoh: アメリカ = Amerika)","mnemonic":"Garis datar dari kiri ke kanan yang menyudut turun ke kiri, lalu garis melengkung turun di tengah.","audio_text":"ア"}'::jsonb, '"ア"'::jsonb, '["ア"]'::jsonb, NULL, 'Huruf Katakana ア (a) terdiri dari 2 goresan tegas bersudut tajam.', 11),
  ('d2000001-0000-4000-8000-000000000018', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「イ」 (i) dengan mengikuti panduan goresan.', '{"target_character":"イ","script":"katakana","romaji":"i","meaning":"Katakana i (contoh: インドネシア = Indonesia)","mnemonic":"Garis miring menyapu dari kanan atas ke kiri bawah, diikuti garis vertikal lurus dari tengahnya ke bawah.","audio_text":"イ"}'::jsonb, '"イ"'::jsonb, '["イ"]'::jsonb, NULL, 'Huruf Katakana イ (i) terdiri dari 2 goresan menyerupai tiang penyangga.', 12),
  ('d2000001-0000-4000-8000-000000000019', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ウ」 (u) dengan mengikuti panduan goresan.', '{"target_character":"ウ","script":"katakana","romaji":"u","meaning":"Katakana u (contoh: ウイルス = virus)","mnemonic":"Garis vertikal kecil di tengah atas, garis vertikal kiri, lalu garis datar atas menyudut turun menyapu ke kiri.","audio_text":"ウ"}'::jsonb, '"ウ"'::jsonb, '["ウ"]'::jsonb, NULL, 'Huruf Katakana ウ (u) memiliki 3 goresan; perhatikan garis vertikal kecil di puncak tengah.', 13),
  ('d2000001-0000-4000-8000-000000000020', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「カ」 (ka) dengan mengikuti panduan goresan.', '{"target_character":"カ","script":"katakana","romaji":"ka","meaning":"Katakana ka (contoh: カメラ = kamera)","mnemonic":"Sama seperti Hiragana か tetapi bersudut tegas dan tanpa titik kecil di kanan atas.","audio_text":"カ"}'::jsonb, '"カ"'::jsonb, '["カ"]'::jsonb, NULL, 'Huruf Katakana カ (ka) terdiri dari 2 goresan tajam.', 14),
  ('d2000001-0000-4000-8000-000000000021', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「サ」 (sa) dengan mengikuti panduan goresan.', '{"target_character":"サ","script":"katakana","romaji":"sa","meaning":"Katakana sa (contoh: サラダ = salad)","mnemonic":"Garis datar panjang ditembus dua garis vertikal; garis kanan lebih panjang dan melengkung ke kiri bawah.","audio_text":"サ"}'::jsonb, '"サ"'::jsonb, '["サ"]'::jsonb, NULL, 'Huruf Katakana サ (sa) terdiri dari 3 goresan; garis vertikal kanan lebih panjang dari yang kiri.', 15),
  ('d2000001-0000-4000-8000-000000000022', 'b0000026-0000-0000-0000-000000000801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「タ」 (ta) dengan mengikuti panduan goresan.', '{"target_character":"タ","script":"katakana","romaji":"ta","meaning":"Katakana ta (contoh: タクシー = taksi)","mnemonic":"Garis miring kiri, garis menyudut turun ke kiri bawah, lalu garis pendek melintang di tengah.","audio_text":"タ"}'::jsonb, '"タ"'::jsonb, '["タ"]'::jsonb, NULL, 'Huruf Katakana タ (ta) memiliki 3 goresan yang rapi dan simetris.', 16),
  ('d2000001-0000-4000-8000-000000000023', 'b0000026-0000-0000-0000-000000001101', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ナ」 (na) dengan mengikuti panduan goresan.', '{"target_character":"ナ","script":"katakana","romaji":"na","meaning":"Katakana na (contoh: ナイフ = pisau)","mnemonic":"Garis datar panjang dari kiri ke kanan, lalu garis vertikal tengah yang melengkung lembut ke kiri bawah.","audio_text":"ナ"}'::jsonb, '"ナ"'::jsonb, '["ナ"]'::jsonb, NULL, 'Huruf Katakana ナ (na) ditulis dalam 2 goresan sederhana.', 11),
  ('d2000001-0000-4000-8000-000000000024', 'b0000026-0000-0000-0000-000000001101', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ハ」 (ha) dengan mengikuti panduan goresan.', '{"target_character":"ハ","script":"katakana","romaji":"ha","meaning":"Katakana ha (contoh: ハンバーガー = burger)","mnemonic":"Dua garis miring terbuka ke luar seperti atap rumah atau huruf V terbalik.","audio_text":"ハ"}'::jsonb, '"ハ"'::jsonb, '["ハ"]'::jsonb, NULL, 'Huruf Katakana ハ (ha) terdiri dari 2 goresan simetris yang tidak saling menyentuh di puncak.', 12),
  ('d2000001-0000-4000-8000-000000000025', 'b0000026-0000-0000-0000-000000001601', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「マ」 (ma) dengan mengikuti panduan goresan.', '{"target_character":"マ","script":"katakana","romaji":"ma","meaning":"Katakana ma (contoh: マンション = apartemen)","mnemonic":"Garis datar atas menyudut miring ke kiri bawah, lalu garis pendek menyilang di ujung bawahnya.","audio_text":"マ"}'::jsonb, '"マ"'::jsonb, '["マ"]'::jsonb, NULL, 'Huruf Katakana マ (ma) terdiri dari 2 goresan tegas.', 11),
  ('d2000001-0000-4000-8000-000000000026', 'b0000026-0000-0000-0000-000000001601', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ラ」 (ra) dengan mengikuti panduan goresan.', '{"target_character":"ラ","script":"katakana","romaji":"ra","meaning":"Katakana ra (contoh: ラーメン = ramen)","mnemonic":"Garis datar pendek di atas, lalu garis datar panjang di bawahnya yang langsung melengkung menyapu ke kiri bawah.","audio_text":"ラ"}'::jsonb, '"ラ"'::jsonb, '["ラ"]'::jsonb, NULL, 'Huruf Katakana ラ (ra) terdiri dari 2 goresan; garis pertama pendek dan sejajar di atas.', 12),
  ('d2000001-0000-4000-8000-000000000027', 'b0000026-0000-0000-0000-000000001801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「シ」 (shi) dengan mengikuti panduan goresan.', '{"target_character":"シ","script":"katakana","romaji":"shi","meaning":"Katakana shi (contoh: シャツ = kemeja)","mnemonic":"Dua titik tersusun vertikal di sisi kiri, lalu goresan panjang menyapu NAIK dari kiri bawah ke kanan atas.","audio_text":"シ"}'::jsonb, '"シ"'::jsonb, '["シ"]'::jsonb, NULL, 'Kunci membedakan シ (shi) dari ツ (tsu): goresan ketiga シ ditarik NAIK dari bawah ke kanan atas.', 11),
  ('d2000001-0000-4000-8000-000000000028', 'b0000026-0000-0000-0000-000000001801', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Katakana 「ツ」 (tsu) dengan mengikuti panduan goresan.', '{"target_character":"ツ","script":"katakana","romaji":"tsu","meaning":"Katakana tsu (contoh: ツアー = tur)","mnemonic":"Dua titik tersusun mendatar di atas, lalu goresan panjang menyapu TURUN dari kanan atas ke kiri bawah.","audio_text":"ツ"}'::jsonb, '"ツ"'::jsonb, '["ツ"]'::jsonb, NULL, 'Kunci membedakan ツ (tsu) dari シ (shi): goresan ketiga ツ ditarik TURUN dari kanan atas ke kiri bawah.', 12),
  ('d2000001-0000-4000-8000-000000000029', 'b0000026-0000-0000-0000-000000000601', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「本」 (hon / moto) dengan mengikuti panduan goresan.', '{"target_character":"本","script":"kanji","romaji":"hon / moto","meaning":"Buku / asal (contoh: 日本 = Jepang)","mnemonic":"Bentuk pohon 木 ditambah satu garis datar kecil di bagian akar bawahnya.","audio_text":"本"}'::jsonb, '"本"'::jsonb, '["本"]'::jsonb, NULL, 'Kanji 本 (buku/asal) ditulis dalam 5 goresan: datar, vertikal, sapuan kiri, sapuan kanan, lalu garis akar.', 11),
  ('d2000001-0000-4000-8000-000000000030', 'b0000026-0000-0000-0000-000000000601', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「名」 (na / mei) dengan mengikuti panduan goresan.', '{"target_character":"名","script":"kanji","romaji":"na / mei","meaning":"Nama (contoh: 名前 = nama)","mnemonic":"Gabungan unsur ''sore hari'' 夕 di atas dan ''mulut'' 口 di bawah — menyebut nama saat hari gelap.","audio_text":"名"}'::jsonb, '"名"'::jsonb, '["名"]'::jsonb, NULL, 'Kanji 名 (nama) memiliki 6 goresan: 3 goresan untuk 夕 di atas dan 3 goresan untuk kotak 口 di bawah.', 12),
  ('d2000001-0000-4000-8000-000000000031', 'b0000026-0000-0000-0000-000000000601', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「前」 (mae / zen) dengan mengikuti panduan goresan.', '{"target_character":"前","script":"kanji","romaji":"mae / zen","meaning":"Depan / sebelum (contoh: 名前 = nama)","mnemonic":"Dua titik atas dan garis datar, lalu unsur 月 di kiri bawah serta dua garis vertikal berkait 刂 di kanan bawah.","audio_text":"前"}'::jsonb, '"前"'::jsonb, '["前"]'::jsonb, NULL, 'Kanji 前 (depan/sebelum) ditulis dalam 9 goresan secara berurutan dari atas ke bawah, kiri ke kanan.', 13),
  ('d2000001-0000-4000-8000-000000000032', 'b0000026-0000-0000-0000-000000000701', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「人」 (hito / jin) dengan mengikuti panduan goresan.', '{"target_character":"人","script":"kanji","romaji":"hito / jin","meaning":"Orang (contoh: 日本人 = orang Jepang)","mnemonic":"Dua goresan miring yang saling menopang seperti dua kaki orang sedang melangkah.","audio_text":"人"}'::jsonb, '"人"'::jsonb, '["人"]'::jsonb, NULL, 'Kanji 人 (orang) ditulis dalam 2 goresan: sapuan kiri panjang, lalu sapuan kanan bertumpu di tengah.', 11),
  ('d2000001-0000-4000-8000-000000000033', 'b0000026-0000-0000-0000-000000000701', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「子」 (ko / shi) dengan mengikuti panduan goresan.', '{"target_character":"子","script":"kanji","romaji":"ko / shi","meaning":"Anak (contoh: 子ども = anak-anak)","mnemonic":"Goresan atas menyudut, garis melengkung turun berkait sebagai badan, lalu garis mendatar lebar seperti tangan terentang.","audio_text":"子"}'::jsonb, '"子"'::jsonb, '["子"]'::jsonb, NULL, 'Kanji 子 (anak) terdiri dari 3 goresan; garis mendatar terakhir melintang di tengah.', 12),
  ('d2000001-0000-4000-8000-000000000034', 'b0000026-0000-0000-0000-000000000701', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「女」 (onna / jo) dengan mengikuti panduan goresan.', '{"target_character":"女","script":"kanji","romaji":"onna / jo","meaning":"Perempuan (contoh: 女の人 = wanita)","mnemonic":"Lengkungan menyudut ke kanan bawah, sapuan melengkung dari kanan ke kiri, lalu garis datar panjang melintang.","audio_text":"女"}'::jsonb, '"女"'::jsonb, '["女"]'::jsonb, NULL, 'Kanji 女 (perempuan) ditulis dalam 3 goresan yang anggun dan seimbang.', 13),
  ('d2000001-0000-4000-8000-000000000035', 'b0000026-0000-0000-0000-000000000701', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「男」 (otoko / dan) dengan mengikuti panduan goresan.', '{"target_character":"男","script":"kanji","romaji":"otoko / dan","meaning":"Laki-laki (contoh: 男の人 = pria)","mnemonic":"Gabungan ''sawah'' 田 di atas dan ''tenaga'' 力 di bawah — tenaga yang bekerja di ladang.","audio_text":"男"}'::jsonb, '"男"'::jsonb, '["男"]'::jsonb, NULL, 'Kanji 男 (laki-laki) ditulis dalam 7 goresan: 5 goresan untuk 田 diikuti 2 goresan untuk 力.', 14),
  ('d2000001-0000-4000-8000-000000000036', 'b0000027-0000-0000-0000-000008000004', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「一」 (ichi / hito) dengan mengikuti panduan goresan.', '{"target_character":"一","script":"kanji","romaji":"ichi / hito","meaning":"Angka satu (contoh: 一つ = satu buah)","mnemonic":"Satu garis mendatar mantap dari kiri ke kanan.","audio_text":"一"}'::jsonb, '"一"'::jsonb, '["一"]'::jsonb, NULL, 'Kanji 一 (satu) ditulis dalam 1 goresan mendatar dari kiri ke kanan.', 11),
  ('d2000001-0000-4000-8000-000000000037', 'b0000027-0000-0000-0000-000008000004', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「二」 (ni / futa) dengan mengikuti panduan goresan.', '{"target_character":"二","script":"kanji","romaji":"ni / futa","meaning":"Angka dua (contoh: 二人 = dua orang)","mnemonic":"Dua garis mendatar sejajar; garis atas lebih pendek dari garis bawah.","audio_text":"二"}'::jsonb, '"二"'::jsonb, '["二"]'::jsonb, NULL, 'Kanji 二 (dua) ditulis dalam 2 goresan mendatar dari atas ke bawah.', 12),
  ('d2000001-0000-4000-8000-000000000038', 'b0000027-0000-0000-0000-000008000004', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「三」 (san / mi) dengan mengikuti panduan goresan.', '{"target_character":"三","script":"kanji","romaji":"san / mi","meaning":"Angka tiga (contoh: 三時 = pukul tiga)","mnemonic":"Tiga garis mendatar sejajar; garis tengah paling pendek dan garis bawah paling panjang.","audio_text":"三"}'::jsonb, '"三"'::jsonb, '["三"]'::jsonb, NULL, 'Kanji 三 (tiga) ditulis dalam 3 goresan mendatar dari atas ke bawah.', 13),
  ('d2000001-0000-4000-8000-000000000039', 'b0000001-0000-0000-0000-000000000014', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「日」 (nichi / hi) dengan mengikuti panduan goresan.', '{"target_character":"日","script":"kanji","romaji":"nichi / hi","meaning":"Matahari / hari (contoh: 日曜日 = Minggu)","mnemonic":"Kotak tegak seperti jendela dengan satu garis datar di tengahnya.","audio_text":"日"}'::jsonb, '"日"'::jsonb, '["日"]'::jsonb, NULL, 'Kanji 日 (hari/matahari) ditulis dalam 4 goresan: kiri, atas-kanan, garis tengah, lalu penutup bawah.', 11),
  ('d2000001-0000-4000-8000-000000000040', 'b0000001-0000-0000-0000-000000000014', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「月」 (getsu / tsuki) dengan mengikuti panduan goresan.', '{"target_character":"月","script":"kanji","romaji":"getsu / tsuki","meaning":"Bulan (contoh: 月曜日 = Senin)","mnemonic":"Seperti sabit berdiri: sisi kiri melengkung keluar, sisi kanan lurus berkait, dengan dua garis datar di dalam.","audio_text":"月"}'::jsonb, '"月"'::jsonb, '["月"]'::jsonb, NULL, 'Kanji 月 (bulan) ditulis dalam 4 goresan dengan proporsi ramping memanjang ke bawah.', 12),
  ('d2000001-0000-4000-8000-000000000041', 'b0000001-0000-0000-0000-000000000014', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「水」 (sui / mizu) dengan mengikuti panduan goresan.', '{"target_character":"水","script":"kanji","romaji":"sui / mizu","meaning":"Air (contoh: 水曜日 = Rabu)","mnemonic":"Garis vertikal berkait di tengah seperti arus sungai, diapit percikan air di kiri dan kanan.","audio_text":"水"}'::jsonb, '"水"'::jsonb, '["水"]'::jsonb, NULL, 'Kanji 水 (air) terdiri dari 4 goresan: tengah dulu, lalu sisi kiri, kemudian dua goresan di sisi kanan.', 13),
  ('d2000001-0000-4000-8000-000000000042', 'b0000001-0000-0000-0000-000000000014', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「山」 (yama / san) dengan mengikuti panduan goresan.', '{"target_character":"山","script":"kanji","romaji":"yama / san","meaning":"Gunung (contoh: 富士山 = Gunung Fuji)","mnemonic":"Tiga puncak gunung: tarik puncak tengah lurus ke bawah dulu, lalu sisi kiri-bawah, dan tutup dengan sisi kanan.","audio_text":"山"}'::jsonb, '"山"'::jsonb, '["山"]'::jsonb, NULL, 'Kanji 山 (gunung) terdiri dari 3 goresan; selalu mulai dari garis vertikal tengah.', 14),
  ('d2000001-0000-4000-8000-000000000043', 'b0000026-0000-0000-0000-000000001201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「食」 (shoku / ta(beru)) dengan mengikuti panduan goresan.', '{"target_character":"食","script":"kanji","romaji":"shoku / ta(beru)","meaning":"Makan (contoh: 食べます = makan)","mnemonic":"Atap tudung saji di atas wadah nasi 良 yang siap disantap.","audio_text":"食"}'::jsonb, '"食"'::jsonb, '["食"]'::jsonb, NULL, 'Kanji 食 (makan) ditulis dalam 9 goresan, dimulai dari dua goresan atap di puncak.', 11),
  ('d2000001-0000-4000-8000-000000000044', 'b0000026-0000-0000-0000-000000001201', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「見」 (ken / mi(ru)) dengan mengikuti panduan goresan.', '{"target_character":"見","script":"kanji","romaji":"ken / mi(ru)","meaning":"Melihat (contoh: 見ます = melihat)","mnemonic":"Unsur ''mata'' 目 di atas sepasang kaki yang melangkah di bawahnya.","audio_text":"見"}'::jsonb, '"見"'::jsonb, '["見"]'::jsonb, NULL, 'Kanji 見 (melihat) ditulis dalam 7 goresan: 5 goresan untuk 目 diikuti 2 goresan kaki di bawah.', 12),
  ('d2000001-0000-4000-8000-000000000045', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「会」 (kai / a(u)) dengan mengikuti panduan goresan.', '{"target_character":"会","script":"kanji","romaji":"kai / a(u)","meaning":"Bertemu / rapat (contoh: 会社 = perusahaan)","mnemonic":"Atap besar di atas yang menaungi pertemuan orang-orang di bawahnya.","audio_text":"会"}'::jsonb, '"会"'::jsonb, '["会"]'::jsonb, NULL, 'Kanji 会 (bertemu/perkumpulan) ditulis dalam 6 goresan dan sering muncul pada kata 会社 dan 会議.', 11),
  ('d2000001-0000-4000-8000-000000000046', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「社」 (sha / yashiro) dengan mengikuti panduan goresan.', '{"target_character":"社","script":"kanji","romaji":"sha / yashiro","meaning":"Perusahaan / masyarakat (contoh: 会社 = perusahaan)","mnemonic":"Sisi kiri adalah unsur altar ネ (4 goresan) berdampingan dengan tanah 土 di kanan.","audio_text":"社"}'::jsonb, '"社"'::jsonb, '["社"]'::jsonb, NULL, 'Kanji 社 (perusahaan/masyarakat) ditulis dalam 7 goresan: 4 goresan radikal kiri dan 3 goresan 土 di kanan.', 12),
  ('d2000001-0000-4000-8000-000000000047', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「仕」 (shi / tsuka(eru)) dengan mengikuti panduan goresan.', '{"target_character":"仕","script":"kanji","romaji":"shi / tsuka(eru)","meaning":"Melayani / bekerja (contoh: 仕事 = pekerjaan)","mnemonic":"Radikal orang berdiri 亻 di kiri dan sarjana/pejuang 士 di kanan (garis atas lebih panjang dari bawah).","audio_text":"仕"}'::jsonb, '"仕"'::jsonb, '["仕"]'::jsonb, NULL, 'Kanji 仕 ditulis dalam 5 goresan dan berpasangan dengan 事 membentuk 仕事 (pekerjaan).', 13),
  ('d2000001-0000-4000-8000-000000000048', 'aebc0c55-8705-4c53-916b-67d0deebb95c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「事」 (ji / koto) dengan mengikuti panduan goresan.', '{"target_character":"事","script":"kanji","romaji":"ji / koto","meaning":"Hal / urusan (contoh: 仕事 = pekerjaan)","mnemonic":"Susunan kotak dan garis mendatar yang ditembus satu garis vertikal berkait lurus dari atas sampai bawah.","audio_text":"事"}'::jsonb, '"事"'::jsonb, '["事"]'::jsonb, NULL, 'Kanji 事 (hal/urusan) ditulis dalam 8 goresan; garis vertikal panjang berkait ditulis paling akhir.', 14),
  ('d2000001-0000-4000-8000-000000000049', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「安」 (an / yasu(i)) dengan mengikuti panduan goresan.', '{"target_character":"安","script":"kanji","romaji":"an / yasu(i)","meaning":"Aman / murah (contoh: 安全 = keselamatan)","mnemonic":"Atap rumah 宀 di atas unsur 女 — tenang dan aman di bawah atap rumah.","audio_text":"安"}'::jsonb, '"安"'::jsonb, '["安"]'::jsonb, NULL, 'Kanji 安 (aman/murah) ditulis dalam 6 goresan: 3 goresan atap 宀 lalu 3 goresan 女.', 11),
  ('d2000001-0000-4000-8000-000000000050', '119ea6f5-61a2-4a6c-8571-d37f851a514a', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「全」 (zen / subete) dengan mengikuti panduan goresan.', '{"target_character":"全","script":"kanji","romaji":"zen / subete","meaning":"Seluruh / lengkap (contoh: 安全 = keselamatan)","mnemonic":"Atap besar 人 di atas unsur 王 (raja/permata) — utuh dan menyeluruh.","audio_text":"全"}'::jsonb, '"全"'::jsonb, '["全"]'::jsonb, NULL, 'Kanji 全 (seluruh/utuh) ditulis dalam 6 goresan: 2 goresan atap diikuti 4 goresan 王.', 12),
  ('d2000001-0000-4000-8000-000000000051', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「病」 (byou / ya(mu)) dengan mengikuti panduan goresan.', '{"target_character":"病","script":"kanji","romaji":"byou / ya(mu)","meaning":"Sakit (contoh: 病院 = rumah sakit)","mnemonic":"Bingkai penyakit 疒 membungkus unsur 丙 di bagian dalam kanan bawah.","audio_text":"病"}'::jsonb, '"病"'::jsonb, '["病"]'::jsonb, NULL, 'Kanji 病 (sakit) ditulis dalam 10 goresan, dimulai dari bingkai 疒 di atas dan kiri.', 11),
  ('d2000001-0000-4000-8000-000000000052', '4f360f65-8d89-4043-bb0c-1132d140b17e', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「院」 (in) dengan mengikuti panduan goresan.', '{"target_character":"院","script":"kanji","romaji":"in","meaning":"Institusi / gedung (contoh: 病院 = rumah sakit)","mnemonic":"Radikal bukit 阝 di sisi kiri (3 goresan) diikuti unsur 完 (selesai/sempurna) di kanan.","audio_text":"院"}'::jsonb, '"院"'::jsonb, '["院"]'::jsonb, NULL, 'Kanji 院 ditulis dalam 10 goresan dan digunakan untuk gedung institusi seperti 病院 (rumah sakit).', 12),
  ('d2000001-0000-4000-8000-000000000053', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「電」 (den) dengan mengikuti panduan goresan.', '{"target_character":"電","script":"kanji","romaji":"den","meaning":"Listrik (contoh: 電車 = kereta listrik)","mnemonic":"Unsur hujan 雨 di atas (8 goresan) dengan kilatan petir melengkung di bawahnya.","audio_text":"電"}'::jsonb, '"電"'::jsonb, '["電"]'::jsonb, NULL, 'Kanji 電 (listrik) ditulis dalam 13 goresan; perhatikan ekor kait bawah yang membelok ke kanan atas.', 11),
  ('d2000001-0000-4000-8000-000000000054', 'b6cc7134-fc28-4525-9d38-53467e7993da', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「車」 (sha / kuruma) dengan mengikuti panduan goresan.', '{"target_character":"車","script":"kanji","romaji":"sha / kuruma","meaning":"Kendaraan / mobil (contoh: 電車 = kereta)","mnemonic":"Bentuk kereta dilihat dari atas: badan kotak di tengah diapit dua as roda datar dan satu poros vertikal.","audio_text":"車"}'::jsonb, '"車"'::jsonb, '["車"]'::jsonb, NULL, 'Kanji 車 (kendaraan) ditulis dalam 7 goresan; garis poros vertikal ditulis paling terakhir.', 12),
  ('d2000001-0000-4000-8000-000000000055', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「旅」 (ryo / tabi) dengan mengikuti panduan goresan.', '{"target_character":"旅","script":"kanji","romaji":"ryo / tabi","meaning":"Perjalanan (contoh: 旅行 = wisata)","mnemonic":"Unsur bendera arah 方 di kiri, lalu dua orang yang berangkat bersama di sisi kanan.","audio_text":"旅"}'::jsonb, '"旅"'::jsonb, '["旅"]'::jsonb, NULL, 'Kanji 旅 (perjalanan) ditulis dalam 10 goresan dan sering dipakai pada kata 旅行 (ryokou).', 11),
  ('d2000001-0000-4000-8000-000000000056', '0433cfee-b60c-4987-b456-60d1c60f829c', NULL, 'writing', 'writing_trace', 'Latih menulis huruf Kanji 「予」 (yo) dengan mengikuti panduan goresan.', '{"target_character":"予","script":"kanji","romaji":"yo","meaning":"Sebelumnya / rencana (contoh: 予約 = reservasi)","mnemonic":"Seperti huruf マ di atas, titik kecil, lalu garis melintang turun berkait seperti huruf 了.","audio_text":"予"}'::jsonb, '"予"'::jsonb, '["予"]'::jsonb, NULL, 'Kanji 予 ditulis dalam 4 goresan dan menjadi inti kata penting seperti 予定 (jadwal) dan 予約 (reservasi).', 12)
INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, acceptable_answers, diagnostic_rubric, explanation, order_index)
VALUES
  ('d2000001-0000-4000-8000-000000000101', '92e8f853-8217-483d-92af-d4801236393d', NULL, 'writing', 'free_typing', 'Ketik kalimat permohonan sangat sopan dalam bahasa Jepang: "Maukah Anda mengajari saya cara menulis formulir ini?"', '{"target_translation":"Maukah Anda mengajari saya cara menulis formulir ini?","audio_text":"書き方を教えていただけませんか。","hint":"Gunakan pola ～ていただけませんか setelah bentuk-TE dari kata kerja mengajari."}'::jsonb, '"書き方を教えていただけませんか。"'::jsonb, '["書き方を教えていただけませんか。","かきかたをおしえていただけませんか","kakikata o oshiete itadakemasen ka"]'::jsonb, NULL, 'Pola 教えていただけませんか digunakan untuk meminta bantuan secara sangat sopan di kantor atau layanan resmi.', 11),
  ('d2000001-0000-4000-8000-000000000102', '92e8f853-8217-483d-92af-d4801236393d', NULL, 'writing', 'free_typing', 'Ketik kalimat permohonan sopan dalam bahasa Jepang: "Maukah Anda mengecek email ini sebentar?"', '{"target_translation":"Maukah Anda mengecek email ini sebentar?","audio_text":"このメールを見ていただけませんか。","hint":"Awali dengan ''kono meeru o'' lalu akhiri dengan pola permohonan sangat sopan untuk melihat."}'::jsonb, '"このメールを見ていただけませんか。"'::jsonb, '["このメールを見ていただけませんか。","このめーるをみていただけませんか","kono meeru o mite itadakemasen ka"]'::jsonb, NULL, 'このメールを見ていただけませんか adalah permintaan sopan yang lazim kepada atasan atau senior.', 12),
  ('d2000001-0000-4000-8000-000000000103', '94e24275-54cb-409e-89c8-265ffe304909', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Di meja sudah disiapkan materi rapat."', '{"target_translation":"Di meja sudah disiapkan materi rapat.","audio_text":"机の上に資料が用意してあります。","hint":"Gunakan partikel が untuk objek hasil persiapan diikuti pola ～てあります."}'::jsonb, '"机の上に資料が用意してあります。"'::jsonb, '["机の上に資料が用意してあります。","つくえのうえにしりょうがよういしてあります","tsukue no ue ni shiryou ga youi shite arimasu"]'::jsonb, NULL, '～が用意してあります menunjukkan barang tersebut sudah sengaja disiapkan dan siap dipakai.', 11),
  ('d2000001-0000-4000-8000-000000000104', '771f0b85-9916-41dd-81f0-7f9cbafb40d3', NULL, 'writing', 'free_typing', 'Ketik kalimat kewajiban dalam bahasa Jepang: "Saya harus menyerahkan laporan besok."', '{"target_translation":"Saya harus menyerahkan laporan besok.","audio_text":"明日レポートを出さなければなりません。","hint":"Gunakan pola keharusan ～なければなりません untuk kata kerja menyerahkan (dasu)."}'::jsonb, '"明日レポートを出さなければなりません。"'::jsonb, '["明日レポートを出さなければなりません。","あしたれぽーとをださなければなりません","ashita repooto o dasanakereba narimasen"]'::jsonb, NULL, '出す -> 出さない -> 出さなければなりません menyatakan kewajiban menyerahkan laporan.', 11),
  ('d2000001-0000-4000-8000-000000000105', '341abfe0-0d08-44cc-9cbc-925dbcff2c99', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya bisa berbicara sedikit bahasa Jepang."', '{"target_translation":"Saya bisa berbicara sedikit bahasa Jepang.","audio_text":"日本語が少し話せます。","hint":"Gunakan bentuk bisa (potensial) dari kata kerja berbicara (hanasu) dengan partikel が."}'::jsonb, '"日本語が少し話せます。"'::jsonb, '["日本語が少し話せます。","にほんごがすこしはなせます","nihongo ga sukoshi hanasemasu"]'::jsonb, NULL, '話す (kelompok 1) berubah menjadi 話せます (bisa berbicara) dan objek kemampuannya ditandai partikel が.', 11),
  ('d2000001-0000-4000-8000-000000000106', '1b9d28b8-37da-4578-a088-aebee5486b04', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Senior membantu mengajari saya pekerjaan."', '{"target_translation":"Senior membantu mengajari saya pekerjaan.","audio_text":"先輩が仕事を教えてくれました。","hint":"Gunakan pola menerima kebaikan dari orang lain (～てくれました)."}'::jsonb, '"先輩が仕事を教えてくれました。"'::jsonb, '["先輩が仕事を教えてくれました。","せんぱいがしごとをおしえてくれました","senpai ga shigoto o oshiete kuremashita"]'::jsonb, NULL, '～てくれました mengungkapkan rasa terima kasih ketika orang lain melakukan kebaikan untuk pembicara.', 11),
  ('d2000001-0000-4000-8000-000000000107', 'd912d2f1-3f0c-4419-9905-a5a5be083ea0', NULL, 'writing', 'free_typing', 'Ketik kalimat saran dalam bahasa Jepang: "Hari ini sebaiknya cepat beristirahat."', '{"target_translation":"Hari ini sebaiknya cepat beristirahat.","audio_text":"今日は早く休んだほうがいいです。","hint":"Gunakan bentuk lampau kata kerja beristirahat diikuti pola saran ～ほうがいいです."}'::jsonb, '"今日は早く休んだほうがいいです。"'::jsonb, '["今日は早く休んだほうがいいです。","きょうははやくやすんだほうがいいです","kyou wa hayaku yasunda hou ga ii desu"]'::jsonb, NULL, '休む -> 休んだほうがいいです dipakai untuk memberi anjuran positif demi kesehatan.', 11),
  ('d2000001-0000-4000-8000-000000000108', '19259446-840c-4bfd-ac51-5591d33f5054', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Karena kereta terlambat, saya menelepon kantor."', '{"target_translation":"Karena kereta terlambat, saya menelepon kantor.","audio_text":"電車が遅れたので、会社に電話します。","hint":"Sambungkan sebab dan akibat dengan penghubung alasan halus ～ので."}'::jsonb, '"電車が遅れたので、会社に電話します。"'::jsonb, '["電車が遅れたので、会社に電話します。","でんしゃがおくれたのでかいしゃにでんわします","densha ga okureta node kaisha ni denwa shimasu"]'::jsonb, NULL, '～ので menyampaikan alasan secara sopan dan objektif dalam situasi kerja.', 11),
  ('d2000001-0000-4000-8000-000000000109', '31fbbfd6-670b-41a1-9e0c-bcdf169ef221', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Kalau pekerjaan selesai, ayo pulang bersama."', '{"target_translation":"Kalau pekerjaan selesai, ayo pulang bersama.","audio_text":"仕事が終わったら、一緒に帰りましょう。","hint":"Ubah kata kerja selesai ke bentuk syarat ～たら lalu akhiri dengan ajakan ～ましょう."}'::jsonb, '"仕事が終わったら、一緒に帰りましょう。"'::jsonb, '["仕事が終わったら、一緒に帰りましょう。","しごとがおわったらいっしょにかえりましょう","shigoto ga owattara issho ni kaerimashou"]'::jsonb, NULL, '終わる -> 終わったら menyatakan syarat waktu ''setelah selesai'' diikuti ajakan 一緒に帰りましょう.', 11),
  ('d2000001-0000-4000-8000-000000000110', '78c8a451-d78a-4f88-8fd8-18b1526df2c8', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya akan memesan ruang rapat terlebih dahulu."', '{"target_translation":"Saya akan memesan ruang rapat terlebih dahulu.","audio_text":"会議室を予約しておきます。","hint":"Gunakan pola persiapan lebih awal ～ておきます setelah kata kerja reservasi."}'::jsonb, '"会議室を予約しておきます。"'::jsonb, '["会議室を予約しておきます。","かいぎしつをよやくしておきます","kaigishitsu o yoyaku shite okimasu"]'::jsonb, NULL, '予約しておきます menekankan bahwa reservasi dilakukan lebih awal sebagai persiapan.', 11),
  ('d2000001-0000-4000-8000-000000000111', '93cc9e35-8317-41f3-8a2e-ee77d414829a', NULL, 'writing', 'free_typing', 'Ketik kalimat bahasa sopan merendah dalam bahasa Jepang: "Saya akan segera membawanya ke sini."', '{"target_translation":"Saya akan segera membawanya ke sini.","audio_text":"すぐお持ちいたします。","hint":"Gunakan bentuk sopan merendah dari ''membawa datang'' (motte mairimasu)."}'::jsonb, '"すぐお持ちいたします。"'::jsonb, '["すぐお持ちいたします。","すぐおもちいたします","sugu omochi itashimasu"]'::jsonb, NULL, 'お持ちいたします adalah bentuk bahasa sopan merendah (お + akar kata kerja + いたします) untuk menawarkan bantuan.', 11),
  ('d2000001-0000-4000-8000-000000000112', '93cc9e35-8317-41f3-8a2e-ee77d414829a', NULL, 'writing', 'free_typing', 'Ketik kalimat bahasa sopan merendah dalam bahasa Jepang: "Saya akan segera mengeceknya."', '{"target_translation":"Saya akan segera mengeceknya.","audio_text":"ただいま確認いたします。","hint":"Gunakan kata kerja konfirmasi (kakunin) dengan bentuk merendah いたします."}'::jsonb, '"ただいま確認いたします。"'::jsonb, '["ただいま確認いたします。","ただいまかくにんいたします","tadaima kakunin itashimasu"]'::jsonb, NULL, 'ただいま確認いたします adalah ungkapan standar layanan pelanggan dan komunikasi kantor di Jepang.', 12),
  ('d2000001-0000-4000-8000-000000000113', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya membiasakan diri minum air setiap pagi."', '{"target_translation":"Saya membiasakan diri minum air setiap pagi.","audio_text":"毎朝水を飲むようにしています。","hint":"Gunakan pola kebiasaan sadar ～ようにしています dengan kata kerja minum."}'::jsonb, '"毎朝水を飲むようにしています。"'::jsonb, '["毎朝水を飲むようにしています。","まいあさみずをのむようにしています","maiasa mizu o nomu you ni shite imasu"]'::jsonb, NULL, 'Bentuk kamus + ようにしています menyatakan kebiasaan baik yang rutin diusahakan.', 11),
  ('d2000001-0000-4000-8000-000000000114', 'eba36f2f-3995-5f9f-a489-2cb98bbff2fc', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya berusaha untuk tidak datang terlambat."', '{"target_translation":"Saya berusaha untuk tidak datang terlambat.","audio_text":"遅刻しないようにしています。","hint":"Gunakan bentuk negatif (～ない) diikuti pola ～ようにしています."}'::jsonb, '"遅刻しないようにしています。"'::jsonb, '["遅刻しないようにしています。","ちこくしないようにしています","chikoku shinai you ni shite imasu"]'::jsonb, NULL, '遅刻しないようにしています menyatakan usaha konsisten agar tidak terlambat.', 12),
  ('d2000001-0000-4000-8000-000000000115', '6aa10a9c-a309-5afe-87f3-303a1d9e4d39', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Diputuskan bahwa bulan depan saya pindah tugas ke Osaka."', '{"target_translation":"Diputuskan bahwa bulan depan saya pindah tugas ke Osaka.","audio_text":"来月大阪へ転勤することになりました。","hint":"Gunakan pola keputusan resmi dari luar diri (～ことになりました)."}'::jsonb, '"来月大阪へ転勤することになりました。"'::jsonb, '["来月大阪へ転勤することになりました。","らいげつおおさかへてんきんすることになりました","raigetsu oosaka e tenkin suru koto ni narimashita"]'::jsonb, NULL, '～ことになりました digunakan untuk menyampaikan keputusan kantor atau organisasi secara objektif.', 11),
  ('d2000001-0000-4000-8000-000000000116', '8f60b7f9-c752-5c02-99ae-19d9d9e11958', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Berkat bantuan semua orang, acaranya berhasil."', '{"target_translation":"Berkat bantuan semua orang, acaranya berhasil.","audio_text":"みんなのおかげでイベントが成功しました。","hint":"Gunakan pola sebab positif ～おかげで untuk mengungkapkan rasa syukur."}'::jsonb, '"みんなのおかげでイベントが成功しました。"'::jsonb, '["みんなのおかげでイベントが成功しました。","みんなのおかげでいべんとがせいこうしました","minna no okage de ibento ga seikou shimashita"]'::jsonb, NULL, '～のおかげで menyoroti kontribusi positif yang membuat hasil baik tercapai.', 11),
  ('d2000001-0000-4000-8000-000000000117', '32c92f6c-c296-59fe-ac70-97a32a865304', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Akibat hujan lebat, pertandingan dibatalkan."', '{"target_translation":"Akibat hujan lebat, pertandingan dibatalkan.","audio_text":"大雨のせいで試合が中止になりました。","hint":"Gunakan pola penyebab kendala/masalah ～せいで setelah kata benda hujan lebat."}'::jsonb, '"大雨のせいで試合が中止になりました。"'::jsonb, '["大雨のせいで試合が中止になりました。","おおあめのせいでしあいがちゅうしになりました","ooame no sei de shiai ga chuushi ni narimashita"]'::jsonb, NULL, '～のせいで menjelaskan penyebab dari kejadian yang tidak diharapkan atau merugikan.', 11),
  ('d2000001-0000-4000-8000-000000000118', 'f6c46fa5-e309-5a50-bd6e-0950353ee258', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya akan menjawab pertanyaan pelanggan dengan sopan."', '{"target_translation":"Saya akan menjawab pertanyaan pelanggan dengan sopan.","audio_text":"質問に対して丁寧に答えます。","hint":"Gunakan pola sasaran tindakan ～に対して setelah kata benda pertanyaan."}'::jsonb, '"質問に対して丁寧に答えます。"'::jsonb, '["質問に対して丁寧に答えます。","しつもんにたいしてていねいにこたえます","shitsumon ni taishite teinei ni kotaemasu"]'::jsonb, NULL, '～に対して menandai sasaran langsung dari sikap atau tanggapan.', 11),
  ('d2000001-0000-4000-8000-000000000119', '90ec6cc0-3dff-5412-b034-3b6ec1707057', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Mumpung masih hangat, silakan makan supnya."', '{"target_translation":"Mumpung masih hangat, silakan makan supnya.","audio_text":"温かいうちにスープを食べてください。","hint":"Gunakan pola ～うちに setelah kata sifat hangat (atatakai)."}'::jsonb, '"温かいうちにスープを食べてください。"'::jsonb, '["温かいうちにスープを食べてください。","あたたかいうちにすーぷをたべてください","atatakai uchi ni suupu o tabete kudasai"]'::jsonb, NULL, '温かいうちに menekankan melakukan sesuatu sebelum keadaan berubah menjadi dingin.', 11),
  ('d2000001-0000-4000-8000-000000000120', '48470705-b669-5414-a39e-ecdd7c9f9eda', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Karena sudah dikirim kemarin, paketnya seharusnya sampai hari ini."', '{"target_translation":"Karena sudah dikirim kemarin, paketnya seharusnya sampai hari ini.","audio_text":"荷物は今日届くはずです。","hint":"Gunakan pola perkiraan logis ～はずです di akhir kalimat."}'::jsonb, '"荷物は今日届くはずです。"'::jsonb, '["荷物は今日届くはずです。","にもつはきょうとどくはずです","nimotsu wa kyou todoku hazu desu"]'::jsonb, NULL, '届くはずです menyatakan keyakinan logis berdasarkan fakta pengiriman.', 11),
  ('d2000001-0000-4000-8000-000000000121', '9732e753-78c3-50a3-b666-22a5adc66314', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Laporan ini dipuji oleh kepala bagian."', '{"target_translation":"Laporan ini dipuji oleh kepala bagian.","audio_text":"この報告書は部長に褒められました。","hint":"Ubah kata kerja memuji (homeru) ke bentuk pasif (di-...) dengan partikel に untuk pelakunya."}'::jsonb, '"この報告書は部長に褒められました。"'::jsonb, '["この報告書は部長に褒められました。","このほうこくしょはぶちょうにほめられました","kono houkokusho wa buchou ni homeraremashita"]'::jsonb, NULL, '褒める -> 褒められました adalah bentuk pasif (di-...) yang bermakna ''dipuji''.', 11),
  ('d2000001-0000-4000-8000-000000000122', '0df92274-024d-5e39-8c25-fda92ab32f74', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya baru saja tiba di stasiun."', '{"target_translation":"Saya baru saja tiba di stasiun.","audio_text":"今駅に着いたばかりです。","hint":"Gunakan bentuk lampau kata kerja tiba diikuti pola ～ばかりです."}'::jsonb, '"今駅に着いたばかりです。"'::jsonb, '["今駅に着いたばかりです。","いまえきについたばかりです","ima eki ni tsuita bakari desu"]'::jsonb, NULL, '着いたばかりです menekankan perasaan pembicara bahwa kedatangan baru saja terjadi.', 11),
  ('d2000001-0000-4000-8000-000000000123', '91662d89-eef5-5734-b1fa-90f73f5178b9', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Tergantung negaranya, budayanya berbeda."', '{"target_translation":"Tergantung negaranya, budayanya berbeda.","audio_text":"国によって文化が違います。","hint":"Gunakan pola keragaman ～によって setelah kata negara."}'::jsonb, '"国によって文化が違います。"'::jsonb, '["国によって文化が違います。","くにによってぶんかがちがいます","kuni ni yotte bunka ga chigaimasu"]'::jsonb, NULL, '～によって menyatakan bahwa sesuatu bervariasi tergantung kondisi atau wilayahnya.', 11),
  ('d2000001-0000-4000-8000-000000000124', '91662d89-eef5-5734-b1fa-90f73f5178b9', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Jadwal berubah karena cuaca."', '{"target_translation":"Jadwal berubah karena cuaca.","audio_text":"天気によって予定が変わります。","hint":"Gunakan pola ～によって untuk menghubungkan cuaca dengan perubahan jadwal."}'::jsonb, '"天気によって予定が変わります。"'::jsonb, '["天気によって予定が変わります。","てんきによってよていがかわります","tenki ni yotte yotei ga kawarimasu"]'::jsonb, NULL, '天気によって予定が変わります adalah kalimat N3 yang sangat berguna untuk pengumuman acara.', 12),
  ('d2000001-0000-4000-8000-000000000125', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Menjelang pembukaan toko baru, kami mempersiapkan acara."', '{"target_translation":"Menjelang pembukaan toko baru, kami mempersiapkan acara.","audio_text":"新店舗の開店にあたって準備を進めています。","hint":"Gunakan pola formal N2 ～にあたって setelah kata pembukaan toko (kaiten)."}'::jsonb, '"新店舗の開店にあたって準備を進めています。"'::jsonb, '["新店舗の開店にあたって準備を進めています。","しんてんぽのかいてんにあたってじゅんびをすすめています","shintenpo no kaiten ni atatte junbi o susumete imasu"]'::jsonb, NULL, '～にあたって digunakan pada momen penting atau persiapan proyek resmi.', 11),
  ('d2000001-0000-4000-8000-000000000126', 'd0e0ca64-70c3-426d-8271-d0e281a31428', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Seiring perkembangan teknologi, cara kerja pun berubah."', '{"target_translation":"Seiring perkembangan teknologi, cara kerja pun berubah.","audio_text":"技術の進歩に伴って働き方も変わります。","hint":"Gunakan pola perubahan beriringan ～に伴って setelah kata perkembangan teknologi."}'::jsonb, '"技術の進歩に伴って働き方も変わります。"'::jsonb, '["技術の進歩に伴って働き方も変わります。","ぎじゅつのしんぽにともなってはたらきかたもかわります","gijutsu no shinpo ni tomonatte hatarakikata mo kawarimasu"]'::jsonb, NULL, '～に伴って menghubungkan dua perubahan yang berjalan bersamaan.', 11),
  ('d2000001-0000-4000-8000-000000000127', '505f6f34-1b40-4967-87c3-d53f240f6e4a', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Tidak terbatas pada hari kerja, akhir pekan pun ramai."', '{"target_translation":"Tidak terbatas pada hari kerja, akhir pekan pun ramai.","audio_text":"平日に限らず週末も混んでいます。","hint":"Gunakan pola perluasan cakupan ～に限らず setelah kata hari kerja (heijitsu)."}'::jsonb, '"平日に限らず週末も混んでいます。"'::jsonb, '["平日に限らず週末も混んでいます。","へいじつにかぎらずしゅうまつもこんでいます","heijitsu ni kagirazu shuumatsu mo konde imasu"]'::jsonb, NULL, '～に限らず berarti ''tidak hanya terbatas pada A, melainkan juga B''.', 11),
  ('d2000001-0000-4000-8000-000000000128', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Karena sudah berjanji, saya tidak mungkin tidak pergi."', '{"target_translation":"Karena sudah berjanji, saya tidak mungkin tidak pergi.","audio_text":"約束したので行かないわけにはいかない。","hint":"Gunakan pola tanggung jawab N2 ～わけにはいかない dengan bentuk negatif pergi."}'::jsonb, '"約束したので行かないわけにはいかない。"'::jsonb, '["約束したので行かないわけにはいかない。","やくそくしたのでいかないわけにはいかない","yakusoku shita node ikanai wake ni wa ikanai"]'::jsonb, NULL, '～ないわけにはいかない menyatakan kewajiban moral/sosial sehingga tidak mungkin tidak melakukannya.', 11),
  ('d2000001-0000-4000-8000-000000000129', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Karena kondisi darurat, rencana terpaksa diubah."', '{"target_translation":"Karena kondisi darurat, rencana terpaksa diubah.","audio_text":"計画を変更せざるを得ない。","hint":"Gunakan pola keterpaksaan ～ざるを得ない dengan pengecualian untuk kata kerja する."}'::jsonb, '"計画を変更せざるを得ない。"'::jsonb, '["計画を変更せざるを得ない。","けいかくをへんこうせざるをえない","keikaku o henkou sezaru o enai"]'::jsonb, NULL, 'Perhatikan pengecualian penting N2: する selalu berubah menjadi せざるを得ない.', 11),
  ('d2000001-0000-4000-8000-000000000130', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Meskipun sibuk, beliau datang menghadiri rapat."', '{"target_translation":"Meskipun sibuk, beliau datang menghadiri rapat.","audio_text":"忙しいにもかかわらず会議に出席した。","hint":"Gunakan pola kontras kuat N2 ～にもかかわらず setelah kata sifat sibuk."}'::jsonb, '"忙しいにもかかわらず会議に出席した。"'::jsonb, '["忙しいにもかかわらず会議に出席した。","いそがしいにもかかわらずかいぎにしゅっせきした","isogashii ni mo kakawarazu kaigi ni shusseki shita"]'::jsonb, NULL, '～にもかかわらず menekankan tindakan yang tetap terjadi di luar dugaan.', 11),
  ('d2000001-0000-4000-8000-000000000131', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Setelah memeriksa isi kontrak, silakan tanda tangan."', '{"target_translation":"Setelah memeriksa isi kontrak, silakan tanda tangan.","audio_text":"内容を確認した上で署名してください。","hint":"Gunakan bentuk lampau kata kerja memeriksa diikuti pola ～上で."}'::jsonb, '"内容を確認した上で署名してください。"'::jsonb, '["内容を確認した上で署名してください。","ないようをかくにんしたうえでしょめいしてください","naiyou o kakunin shita ue de shomei shite kudasai"]'::jsonb, NULL, 'V-た + 上で menegaskan langkah pertama harus tuntas dulu sebelum langkah berikutnya.', 11),
  ('d2000001-0000-4000-8000-000000000132', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Kesadaran masyarakat terhadap lingkungan sedang terus meningkat."', '{"target_translation":"Kesadaran masyarakat terhadap lingkungan sedang terus meningkat.","audio_text":"環境への意識が高まりつつある。","hint":"Gunakan pola tren berlangsung ～つつある setelah akar kata kerja meningkat (takamaru)."}'::jsonb, '"環境への意識が高まりつつある。"'::jsonb, '["環境への意識が高まりつつある。","かんきょうへのいしきがたかまりつつある","kankyou e no ishiki ga takamaritsutsu aru"]'::jsonb, NULL, '高まりつつある menggambarkan proses perubahan bertahap yang sedang berlangsung.', 11),
  ('d2000001-0000-4000-8000-000000000133', 'a3645058-b04b-4958-9c91-35a2e545af95', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Kesalahan kecil bisa saja memicu kecelakaan besar."', '{"target_translation":"Kesalahan kecil bisa saja memicu kecelakaan besar.","audio_text":"小さなミスが大きな事故につながりかねない。","hint":"Gunakan pola peringatan risiko ～かねない setelah akar kata kerja mengarah/terhubung."}'::jsonb, '"小さなミスが大きな事故につながりかねない。"'::jsonb, '["小さなミスが大きな事故につながりかねない。","ちいさなみすがおおきなじこにつながりかねない","chiisana misu ga ookina jiko ni tsunagarikanenai"]'::jsonb, NULL, '～かねない dipakai untuk memperingatkan kemungkinan timbulnya akibat buruk.', 11),
  ('d2000001-0000-4000-8000-000000000134', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', NULL, 'writing', 'free_typing', 'Ketik kalimat bahasa sopan menghormati lawan bicara: "Apakah Bapak Direktur sudah melihat laporan tersebut?"', '{"target_translation":"Apakah Bapak Direktur sudah melihat laporan tersebut?","audio_text":"社長は報告書をご覧になりましたか。","hint":"Gunakan bentuk sopan khusus dari ''melihat'' (goran ni naru)."}'::jsonb, '"社長は報告書をご覧になりましたか。"'::jsonb, '["社長は報告書をご覧になりましたか。","しゃちょうはほうこくしょをごらんになりましたか","shachou wa houkokusho o goran ni narimashita ka"]'::jsonb, NULL, 'ご覧になりましたか adalah bentuk bahasa sopan menghormati lawan bicara baku untuk 見る.', 11),
  ('d2000001-0000-4000-8000-000000000135', '352f58c1-2360-414e-864e-6f6c115b2f16', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Baru setelah sampai di tahap ini, saya menyadari kesalahannya."', '{"target_translation":"Baru setelah sampai di tahap ini, saya menyadari kesalahannya.","audio_text":"ここに至ってはじめて誤りに気づいた。","hint":"Gunakan pola titik kritis N1 ここに至って diikuti はじめて."}'::jsonb, '"ここに至ってはじめて誤りに気づいた。"'::jsonb, '["ここに至ってはじめて誤りに気づいた。","ここにいたってはじめてあやまりにきづいた","koko ni itatte hajimete ayamari ni kizuita"]'::jsonb, NULL, 'ここに至ってはじめて menandai kesadaran yang baru muncul saat keadaan sudah jauh berjalan.', 11),
  ('d2000001-0000-4000-8000-000000000136', '488f5061-8241-4269-b37d-897b0e2137c2', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Perusahaan terpaksa mengubah rencananya akibat badai."', '{"target_translation":"Perusahaan terpaksa mengubah rencananya akibat badai.","audio_text":"計画の変更を余儀なくされた。","hint":"Gunakan pola keterpaksaan resmi N1 ～を余儀なくされた setelah kata benda perubahan."}'::jsonb, '"計画の変更を余儀なくされた。"'::jsonb, '["計画の変更を余儀なくされた。","けいかくのへんこうをよぎなくされた","keikaku no henkou o yoginaku sareta"]'::jsonb, NULL, '～を余儀なくされた selalu didahului kata benda tindakan tanpa する.', 11),
  ('d2000001-0000-4000-8000-000000000137', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Meskipun sudah musim semi, hari-hari dingin masih berlanjut."', '{"target_translation":"Meskipun sudah musim semi, hari-hari dingin masih berlanjut.","audio_text":"春とはいえまだ寒い日が続く。","hint":"Gunakan pola pengakuan disertai kontras N1 ～とはいえ setelah kata musim semi."}'::jsonb, '"春とはいえまだ寒い日が続く。"'::jsonb, '["春とはいえまだ寒い日が続く。","はるとはいえまださむいひがつづく","haru to wa ie mada samui hi ga tsuzuku"]'::jsonb, NULL, '春とはいえ mengakui fakta musim semi sambil menekankan kenyataan bahwa udara masih dingin.', 11),
  ('d2000001-0000-4000-8000-000000000138', '83690cd2-583b-46be-b4b2-d39e09879a7c', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Terhitung hari ini, penerimaan pendaftaran resmi ditutup."', '{"target_translation":"Terhitung hari ini, penerimaan pendaftaran resmi ditutup.","audio_text":"本日をもって受付を終了いたします。","hint":"Gunakan pola batas waktu resmi N1 ～をもって setelah kata hari ini (honjitsu)."}'::jsonb, '"本日をもって受付を終了いたします。"'::jsonb, '["本日をもって受付を終了いたします。","ほんじつをもってうけつけをしゅうりょういたします","honjitsu o motte uketsuke o shuuryou itashimasu"]'::jsonb, NULL, '本日をもって adalah ungkapan pengumuman resmi untuk menandai batas akhir layanan.', 11),
  ('d2000001-0000-4000-8000-000000000139', '469fe96f-b404-4f61-b03f-ba3c45835ae1', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Tindakan tersebut amat sangat berbahaya."', '{"target_translation":"Tindakan tersebut amat sangat berbahaya.","audio_text":"その行為は危険極まりない。","hint":"Gunakan pola tingkat ekstrem N1 ～極まりない setelah kata sifat berbahaya (kiken)."}'::jsonb, '"その行為は危険極まりない。"'::jsonb, '["その行為は危険極まりない。","そのこういはきけんきわまりない","sono koui wa kiken kiwamarinai"]'::jsonb, NULL, '危険極まりない menyatakan kritik tegas bahwa sesuatu berada di tingkat bahaya ekstrem.', 11),
  ('d2000001-0000-4000-8000-000000000140', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Saya sudah berusaha sebaik mungkin dengan cara saya sendiri."', '{"target_translation":"Saya sudah berusaha sebaik mungkin dengan cara saya sendiri.","audio_text":"私は私なりに努力しました。","hint":"Gunakan pola sesuai kapasitas diri N1 ～なりに."}'::jsonb, '"私は私なりに努力しました。"'::jsonb, '["私は私なりに努力しました。","わたしはわたしなりにどりょくしました","watashi wa watashi nari ni doryoku shimashita"]'::jsonb, NULL, '私は私なりに menyampaikan usaha tulus sesuai kemampuan sendiri secara rendah hati.', 11),
  ('d2000001-0000-4000-8000-000000000141', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Pidatonya pasti akan menggugah haru semua orang."', '{"target_translation":"Pidatonya pasti akan menggugah haru semua orang.","audio_text":"彼のスピーチはみんなを感動させずにはおかない。","hint":"Gunakan pola dampak niscaya N1 ～ずにはおかない dengan bentuk membuat terharu."}'::jsonb, '"彼のスピーチはみんなを感動させずにはおかない。"'::jsonb, '["彼のスピーチはみんなを感動させずにはおかない。","かれのすぴーちはみんなをかんどうさせずにはおかない","kare no supiichi wa minna o kandou sasezu ni wa okanai"]'::jsonb, NULL, '感動させずにはおかない menekankan kekuatan pidato yang pasti menggugah emosi pendengar.', 11),
  ('d2000001-0000-4000-8000-000000000142', '0db7ce8d-d908-4752-ada3-98be543827ad', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Jika sudah sampai level profesional, latihannya pun sangat ketat."', '{"target_translation":"Jika sudah sampai level profesional, latihannya pun sangat ketat.","audio_text":"プロともなると練習も厳しい。","hint":"Gunakan pola tingkatan khusus N1 ～ともなると setelah kata profesional (puro)."}'::jsonb, '"プロともなると練習も厳しい。"'::jsonb, '["プロともなると練習も厳しい。","ぷろともなるとれんしゅうもきびしい","puro to mo naru to renshuu mo kibishii"]'::jsonb, NULL, 'プロともなると menyoroti standar tinggi yang otomatis menyertai status profesional.', 11),
  ('d2000001-0000-4000-8000-000000000143', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Tanpa memandang alasannya, keterlambatan tidak diperbolehkan."', '{"target_translation":"Tanpa memandang alasannya, keterlambatan tidak diperbolehkan.","audio_text":"理由のいかんによらず遅刻は認められません。","hint":"Gunakan pola aturan mutlak N1 ～のいかんによらず setelah kata alasan (riyuu)."}'::jsonb, '"理由のいかんによらず遅刻は認められません。"'::jsonb, '["理由のいかんによらず遅刻は認められません。","りゆうのいかんによらずちこくはみとめられません","riyuu no ikan ni yorazu chikoku wa mitomeraremasen"]'::jsonb, NULL, '理由のいかんによらず menegaskan ketentuan resmi yang berlaku tanpa pengecualian.', 11),
  ('d2000001-0000-4000-8000-000000000144', '67e2f856-1589-44aa-bc3f-658f80017a53', NULL, 'writing', 'free_typing', 'Ketik dalam bahasa Jepang: "Riset ini sungguh layak untuk dipercaya."', '{"target_translation":"Riset ini sungguh layak untuk dipercaya.","audio_text":"この研究は信頼に足る。","hint":"Gunakan pola kelayakan formal N1 ～に足る setelah kata kepercayaan (shinrai)."}'::jsonb, '"この研究は信頼に足る。"'::jsonb, '["この研究は信頼に足る。","このけんきゅうはしんらいにたる","kono kenkyuu wa shinrai ni taru"]'::jsonb, NULL, '信頼に足る adalah ungkapan formal tingkat N1 yang berarti ''layak dipercaya''.', 11)
