-- Migration 000020: Extend exercises_exercise_type_check with writing_trace & free_typing
-- and seed 56 interactive Japanese writing_trace exercises (N5-N4) + 44 free_typing exercises (N4-N1).
BEGIN;

-- 1. Extend exercises_exercise_type_check constraint
ALTER TABLE exercises DROP CONSTRAINT IF EXISTS exercises_exercise_type_check;
ALTER TABLE exercises ADD CONSTRAINT exercises_exercise_type_check
  CHECK (exercise_type IN ('sentence_builder', 'fill_blank', 'listening_choice', 'speaking_repeat', 'dialogue_roleplay', 'writing_trace', 'free_typing'));

-- 2. Seed 56 writing_trace exercises across N5 (Hiragana, Katakana, Kanji) & N4 (Kanji)
ON CONFLICT (id) DO NOTHING;

-- 3. Seed 44 free_typing exercises across N4, N3, N2, and N1
ON CONFLICT (id) DO NOTHING;

COMMIT;
